import * as React from 'react';

import { cn } from '@/lib/utils';

/**
 * The dashboard's layout: two tiles across on a phone or narrow pane, four
 * from a 48rem container. Count tiles take one cell; `RecentRecords` takes two.
 * Sized by its own width, so it works in a split pane as well as a page.
 */
export function DashboardGrid({ className, children, ...props }: React.ComponentProps<'div'>) {
	return (
		<div className="@container/dashboard w-full">
			{/* Items keep their own height, so a count tile beside a tall list does not stretch to match it. */}
			<div className={cn('grid grid-cols-1 items-start gap-3 @xs/dashboard:grid-cols-2 @3xl/dashboard:grid-cols-4', className)} {...props}>
				{children}
			</div>
		</div>
	);
}

export { DashboardGrid } from '@/components/ui/dashboard-tiles/dashboard-grid';
export { RecentRecords } from '@/components/ui/dashboard-tiles/recent-records';
export type { RecentRecordsProps } from '@/components/ui/dashboard-tiles/recent-records';
export { ResourceCountTile } from '@/components/ui/dashboard-tiles/resource-count-tile';
export type { ResourceCountTileProps } from '@/components/ui/dashboard-tiles/resource-count-tile';
export { StatTile, tileClass } from '@/components/ui/dashboard-tiles/stat-tile';
export type { StatTileProps } from '@/components/ui/dashboard-tiles/stat-tile';

'use client';

import * as React from 'react';

import { cn } from '@/lib/utils';
import { useResourceDefinition, useResourceIcon, useResourceKit } from '@/components/ui/resource-kit/context';
import { FieldValue, linkClass } from '@/components/ui/resource-kit/field-value';
import { fieldFormat, inSentence, recordId, visibleFields } from '@/components/ui/resource-kit/fields';
import { errorMessage } from '@/components/ui/resource-kit/form-values';
import { formatFieldText } from '@/components/ui/resource-kit/format';
import { useRelationLabels, useRowTitles } from '@/components/ui/resource-kit/labels';
import { queryFailure, useResourceList } from '@/components/ui/resource-kit/queries';
import type { ListQuery, ResourceRef } from '@/components/ui/resource-kit/types';
import { dashedRule, EmptyState, Panel } from '@/components/ui/workspace-kit/surface';

export type RecentRecordsProps = {
	resource: ResourceRef;
	/** Rows to show. Defaults to 5. */
	limit?: number;
	/** Defaults to the resource's default sort, else newest first by `createdAt` when the resource has that field. */
	sort?: ListQuery['sort'];
	/** Equality filters, e.g. `{ status: 'open' }`. */
	filters?: Record<string, unknown>;
	/** Defaults to "Recent <label>". */
	title?: React.ReactNode;
	className?: string;
};

const DATE_FORMATS = new Set(['date', 'datetime', 'relative']);

/**
 * The latest records of a resource on a dashboard panel: each title links to
 * the record, with one detail beside it and when it was made.
 */
export function RecentRecords({ resource: resourceRef, limit = 5, sort, filters, title, className }: RecentRecordsProps) {
	const resource = useResourceDefinition(resourceRef);
	const icon = useResourceIcon(resource);
	const { router, locale, currency, now } = useResourceKit();
	const order = sort ?? resource.defaultSort ?? (resource.fields.createdAt ? { field: 'createdAt', direction: 'desc' as const } : undefined);
	const list = useResourceList(resource, { sort: order, offset: 0, limit, filters });
	const rows = list.data?.rows ?? [];
	const failure = queryFailure(list);
	const columns = React.useMemo(() => visibleFields(resource, resource.columns).filter((field) => field.name !== resource.titleField), [resource]);
	// One detail beside the title (the first column that is not a date) and the time on the right.
	const detail = columns.find((field) => !DATE_FORMATS.has(fieldFormat(field)) && !field.relation?.many);
	const timeField = order?.field && resource.fields[order.field] && DATE_FORMATS.has(fieldFormat(resource.fields[order.field]!)) ? resource.fields[order.field] : undefined;
	const relationLabel = useRelationLabels(detail ? [detail] : [], rows);
	const titleOf = useRowTitles(resource, rows);
	const label = inSentence(resource.label);

	return (
		<Panel
			title={title ?? `Recent ${label}`}
			actions={
				<router.Link href={router.listHref(resource.name)} className={cn(linkClass, 'text-xs text-muted-foreground hover:text-foreground')}>
					View all
				</router.Link>
			}
			bodyClassName="px-0 pb-1"
			className={cn('col-span-full @3xl/dashboard:col-span-2', className)}
		>
			{list.isPending && !list.failureReason ? (
				<ul aria-busy="true" aria-label="Loading" className="motion-safe:animate-pulse">
					{Array.from({ length: Math.min(limit, 4) }, (_, index) => (
						<li key={index} className={cn('flex items-center gap-3 px-4 py-2.5', index > 0 && cn('border-t', dashedRule))}>
							<span className="h-2.5 w-36 rounded-full bg-muted" />
							<span className="ms-auto h-2.5 w-16 rounded-full bg-muted" />
						</li>
					))}
				</ul>
			) : failure ? (
				<p role="alert" className="px-4 pb-3 text-[0.8125rem] text-destructive [overflow-wrap:anywhere]">
					{errorMessage(failure)}
				</p>
			) : rows.length === 0 ? (
				<EmptyState icon={icon} title={`No ${label} yet`} className="py-6" />
			) : (
				<ul className="flex flex-col text-[0.8125rem]">
					{rows.map((row, index) => {
						const id = recordId(resource, row);
						const name = titleOf(row) ?? '…';
						const time = timeField ? formatFieldText({ ...timeField, format: 'relative' }, row[timeField.name], { locale, currency, now }) : null;
						return (
							<li key={id || index} className={cn('flex min-w-0 items-center gap-3 px-4 py-2', index > 0 && cn('border-t', dashedRule))}>
								<span className="flex min-w-0 flex-1 flex-col">
									<router.Link href={router.detailHref(resource.name, id)} className={cn(linkClass, 'block min-w-0 font-medium')}>
										<span dir="auto" title={name} className="block truncate">
											{name}
										</span>
									</router.Link>
									{detail ? (
										<span className="min-w-0 text-xs text-muted-foreground">
											<FieldValue resource={resource} field={detail} row={row} relation={relationLabel(detail, row)} truncate />
										</span>
									) : null}
								</span>
								{time ? <span className="shrink-0 text-xs text-muted-foreground tabular-nums">{time}</span> : null}
							</li>
						);
					})}
				</ul>
			)}
		</Panel>
	);
}

'use client';

import * as React from 'react';

import { formatCount } from '@/lib/intl';
import { useResourceDefinition, useResourceIcon, useResourceKit } from '@/components/ui/resource-kit/context';
import { useResourceList } from '@/components/ui/resource-kit/queries';
import type { ListQuery, ResourceRef } from '@/components/ui/resource-kit/types';
import { StatTile } from '@/components/ui/dashboard-tiles/stat-tile';

export type ResourceCountTileProps = {
	resource: ResourceRef;
	/** Defaults to the resource's plural label. */
	label?: React.ReactNode;
	/** Equality filters, e.g. `{ status: 'open' }` for "Open deals". */
	filters?: Record<string, unknown>;
	hint?: React.ReactNode;
	className?: string;
};

/**
 * How many records a resource has, optionally filtered, read as one row's
 * `totalCount` from the source. Links to the resource's list.
 */
export function ResourceCountTile({ resource: resourceRef, label, filters, hint, className }: ResourceCountTileProps) {
	const resource = useResourceDefinition(resourceRef);
	const icon = useResourceIcon(resource);
	const { router, locale } = useResourceKit();
	const query: ListQuery = { offset: 0, limit: 1, filters };
	const list = useResourceList(resource, query);
	return (
		<StatTile
			label={label ?? resource.label}
			icon={icon}
			value={list.isError ? '—' : formatCount(list.data?.totalCount ?? 0, locale)}
			hint={list.isError ? 'Couldn’t load' : hint}
			loading={list.isPending}
			href={router.listHref(resource.name)}
			className={className}
		/>
	);
}

'use client';

import { ChevronRightIcon, type LucideIcon } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { useOptionalResourceKit } from '@/components/ui/resource-kit/context';
import { focusRingClass } from '@/components/ui/workspace-kit/primitives';
import { StatTile as StatFigure } from '@/components/ui/workspace-kit/surface';

/** The card every dashboard tile sits on. */
export const tileClass = 'rounded-xl bg-card shadow-card';

export type StatTileProps = {
	label: React.ReactNode;
	value: React.ReactNode;
	hint?: React.ReactNode;
	/** Makes the whole tile a link, through the resource kit's router when one encloses it. */
	href?: string;
	icon?: LucideIcon;
	/** Draws a placeholder figure while the value loads. */
	loading?: boolean;
	className?: string;
};

/** A figure on its own card: a label, a large tabular value, and a hint. Links to where the number comes from. */
export function StatTile({ label, value, hint, href, icon, loading = false, className }: StatTileProps) {
	const kit = useOptionalResourceKit();
	const figure = (
		<StatFigure
			label={label}
			icon={icon}
			value={loading ? <span aria-hidden="true" className="my-1 block h-5 w-16 rounded-full bg-muted motion-safe:animate-pulse" /> : value}
			// A tile without a hint keeps the hint line, so tiles in a row end level.
			hint={hint ?? <span aria-hidden="true">{'\u00a0'}</span>}
			className="min-w-0 flex-1"
		/>
	);
	if (!href) return <div className={cn(tileClass, 'flex items-start p-4', className)} aria-busy={loading || undefined}>{figure}</div>;
	const linkClass = cn(
		tileClass,
		'group/tile flex items-start gap-2 p-4 no-underline transition-colors duration-(--duration-fast) hover:bg-muted/40',
		focusRingClass,
		className,
	);
	const content = (
		<>
			{figure}
			<ChevronRightIcon
				aria-hidden="true"
				className="size-3.5 shrink-0 text-subtle-foreground transition-transform duration-(--duration-fast) group-hover/tile:translate-x-0.5 group-hover/tile:text-muted-foreground rtl:rotate-180"
			/>
		</>
	);
	return kit ? (
		<kit.router.Link href={href} className={linkClass}>
			{content}
		</kit.router.Link>
	) : (
		<a href={href} className={linkClass}>
			{content}
		</a>
	);
}
